function validate([arr, k]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100000) return 'arr needs 2 to 100000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value is an integer from 1 to 1000000.';
  if (new Set(arr).size !== arr.length) return 'The values in arr must be distinct.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is an integer from 1 to 10^9.';
  return null;
}

