function getWinner(arr, k) {
  const queue = arr.slice();
  const top = Math.max(...queue);
  let streak = 0;
  while (true) {
    if (queue[0] === top) return top;
    const a = queue[0], b = queue[1];
    if (a > b) { queue.splice(1, 1); queue.push(b); streak++; }
    else { queue.shift(); queue.push(a); streak = 1; }
    if (streak >= k) return queue[0];
  }
}

