function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 7);
  const limit = size === 'large' ? 1000000 : 20;
  const seen = new Set();
  const arr = [];
  while (arr.length < n) {
    const v = 1 + Math.floor(rand() * limit);
    if (!seen.has(v)) { seen.add(v); arr.push(v); }
  }
  const pick = rand();
  let k;
  if (pick < 0.15) k = 1000000000;
  else if (size === 'large') k = 1 + Math.floor(rand() * (pick < 0.6 ? 20 : 2500));
  else k = 1 + Math.floor(rand() * (n + 2));
  return [arr, k];
}
